SELECT sku, gtin, name, pack, case_units, case_kg, flow, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%' OR pack ILIKE '%atta%';

SELECT audit_ts, sku, status FROM store.shelf_audits
WHERE sku = 'ATTA-WW-5KG' AND audit_ts >= DATE '2026-06-01' AND audit_ts < DATE '2026-07-01'
ORDER BY audit_ts;
